function validate(input) {
  const [fn, args, t, cancelTimeMs] = input;
  if (!['double', 'sum', 'product', 'max'].includes(fn)) return 'fn must be "double", "sum", "product" or "max".';
  if (!Array.isArray(args) || args.length < 1 || args.length > 10) return 'args must hold 1 to 10 values.';
  if (!args.every((x) => Number.isInteger(x) && x >= -10 && x <= 10)) return 'Each argument must be an integer from -10 to 10.';
  if (!Number.isInteger(t) || t < 30 || t > 100) return 't must be an integer from 30 to 100.';
  if (!Number.isInteger(cancelTimeMs) || cancelTimeMs < 10 || cancelTimeMs > 500) return 'cancelTimeMs must be an integer from 10 to 500.';
  if (cancelTimeMs % t === 0) return 'Pick a cancelTimeMs that is not a multiple of t, so no call coincides with cancelling.';
  return null;
}

