function adapt(input, solve, kit) {
  const [name, args, t, cancelTimeMs] = input;
  const compute = {
    double: (values) => values[0] * 2,
    sum: (values) => values.reduce((total, x) => total + x, 0),
    product: (values) => values.reduce((total, x) => total * x, 1),
    max: (values) => Math.max(...values),
  }[name];
  const calls = [];
  const start = Date.now();
  const fn = (...received) => {
    const returned = compute(received);
    calls.push({ time: Date.now() - start, returned });
    kit.trace(`fn(${received.join(', ')}) is called and returns ${returned}`);
    return returned;
  };
  kit.trace(`cancellable(fn, [${args.join(', ')}], ${t}) is called`);
  const cancelFn = solve(fn, args, t);
  if (typeof cancelFn !== 'function') throw new Error('cancellable must return a cancel function.');
  setTimeout(() => {
    kit.trace('cancelFn is called');
    cancelFn();
  }, cancelTimeMs);
  // Any call that was not cancelled would come before this moment.
  return new Promise((resolve) => setTimeout(() => resolve(calls), cancelTimeMs + t + 15));
}

