function generate(rand, size) {
  const names = ['double', 'sum', 'product', 'max'];
  const fn = names[Math.floor(rand() * names.length)];
  const length = 1 + Math.floor(rand() * (size === 'small' ? 4 : 10));
  const args = Array.from({ length }, () => Math.floor(rand() * 21) - 10);
  const t = size === 'small' ? 30 + Math.floor(rand() * 71) : 30 + Math.floor(rand() * 11);
  const top = size === 'small' ? 250 : 500, low = size === 'small' ? 10 : 400;
  let cancelTimeMs = low + Math.floor(rand() * (top - low + 1));
  if (cancelTimeMs % t === 0) cancelTimeMs -= 1;
  return [fn, args, t, cancelTimeMs];
}
